package eit_image_availability_coordinator.EIT_Image_Availability_Coordinator

import org.sireum._
import art.Art
import eit_image_availability_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait ReviewLifecycle_coordination_review_lifecycle_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITImageAvailabilitySystem_Instance_coordination_review_lifecycle)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITImageAvailabilitySystem_Instance_coordination_review_lifecycle)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITImageAvailabilitySystem_Instance_coordination_review_lifecycle)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITImageAvailabilitySystem_Instance_coordination_review_lifecycle)
  }

  /** helper function to set the values of all input ports.
   * @param reviewFacts payload for data port reviewFacts
   * @param recoveryFrame payload for data port recoveryFrame
   * @param availabilityFrame payload for data port availabilityFrame
   */
  def put_concrete_inputs(reviewFacts : EIT_Image_Availability_Coordinator.ReviewFacts.Type,
                          recoveryFrame : EIT_Image_Availability_Coordinator.RecoveryFrame,
                          availabilityFrame : EIT_Image_Availability_Coordinator.AvailabilityDecisionFrame): Unit = {
    put_reviewFacts(reviewFacts)
    put_recoveryFrame(recoveryFrame)
    put_availabilityFrame(availabilityFrame)
  }


  /** helper function to check ReviewLifecycle_coordination_review_lifecycle's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param reviewFrame method that will be called with the value of the outgoing data
   *        port 'reviewFrame'.
   */
  def check_concrete_output(reviewFrame: EIT_Image_Availability_Coordinator.ReviewFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val reviewFrameValue: EIT_Image_Availability_Coordinator.ReviewFrame = get_reviewFrame().get
    if(!reviewFrame(reviewFrameValue)) {
      testFailures = testFailures :+ st"'reviewFrame' did not match expected: value of the outgoing data port is ${reviewFrameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_reviewFacts(value : EIT_Image_Availability_Coordinator.ReviewFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_review_lifecycle.operational_api.reviewFacts_Id, EIT_Image_Availability_Coordinator.ReviewFacts_Payload(value))
  }

  // setter for in DataPort
  def put_recoveryFrame(value : EIT_Image_Availability_Coordinator.RecoveryFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_review_lifecycle.operational_api.recoveryFrame_Id, EIT_Image_Availability_Coordinator.RecoveryFrame_Payload(value))
  }

  // setter for in DataPort
  def put_availabilityFrame(value : EIT_Image_Availability_Coordinator.AvailabilityDecisionFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_review_lifecycle.operational_api.availabilityFrame_Id, EIT_Image_Availability_Coordinator.AvailabilityDecisionFrame_Payload(value))
  }

  // getter for out DataPort
  def get_reviewFrame(): Option[EIT_Image_Availability_Coordinator.ReviewFrame] = {
    val value: Option[EIT_Image_Availability_Coordinator.ReviewFrame] = get_reviewFrame_payload() match {
      case Some(EIT_Image_Availability_Coordinator.ReviewFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port reviewFrame.  Expecting 'EIT_Image_Availability_Coordinator.ReviewFrame_Payload' but received ${v}")
      case _ => None[EIT_Image_Availability_Coordinator.ReviewFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_reviewFrame_payload(): Option[EIT_Image_Availability_Coordinator.ReviewFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_review_lifecycle.initialization_api.reviewFrame_Id).asInstanceOf[Option[EIT_Image_Availability_Coordinator.ReviewFrame_Payload]]
  }

}
